def ring_small_world(n: int, k: int, p: float, rng: random.Random) -> Dict[int, set]:
    adj = {i: set() for i in range(n)}
    half = max(1, min(k // 2, (n - 1) // 2))
    for i in range(n):
        for d in range(1, half + 1):
            j = (i + d) % n
            if j != i:
                adj[i].add(j)
                adj[j].add(i)
    for i in range(n):
        for d in range(1, half + 1):
            j = (i + d) % n
            if rng.random() < p:
                if j in adj[i]:
                    adj[i].discard(j)
                    adj[j].discard(i)
                # Sample a new neighbor without building an O(n) candidate list
                if len(adj[i]) >= n - 1:
                    continue  # fully connected; skip rewiring
                for _ in range(10):  # bounded attempts
                    u = rng.randrange(n)
                    if u != i and u not in adj[i]:
                        adj[i].add(u)
                        adj[u].add(i)
                        break
                else:
                    # fallback: restore original edge
                    adj[i].add(j)
                    adj[j].add(i)
    return adj
